function maxUniqueSplit(s) {
  const seen = new Set();
  let best = 0;

  const backtrack = (start) => {
    if (start === s.length) {
      best = Math.max(best, seen.size);
      return;
    }
    if (seen.size + (s.length - start) <= best) {
      return;
    }
    for (let end = start + 1; end <= s.length; end++) {
      const piece = s.slice(start, end);
      if (seen.has(piece)) {
        continue;
      }
      seen.add(piece);
      backtrack(end);
      seen.delete(piece);
    }
  };

  backtrack(0);
  return best;
}

