function maxUniqueSplit(s) {
  const n = s.length;
  let best = 1;
  // Each of the n - 1 gaps between characters is either cut or not.
  for (let mask = 0; mask < (1 << (n - 1)); mask++) {
    const parts = [];
    let from = 0;
    for (let gap = 0; gap < n - 1; gap++) {
      if (mask & (1 << gap)) {
        parts.push(s.substring(from, gap + 1));
        from = gap + 1;
      }
    }
    parts.push(s.substring(from));
    if (new Set(parts).size === parts.length && parts.length > best) best = parts.length;
  }
  return best;
}

