function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const n = size === 'large' ? 12 + Math.floor(rand() * 5) : 1 + Math.floor(rand() * 10);
  const pick = rand();
  const alphabet = pick < 0.25 ? 1 : pick < 0.6 ? 2 : pick < 0.85 ? 3 : 26;
  let s = '';
  for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * alphabet)];
  return [s];
}
